head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ111P08';

/*최상단 선언 */
scwin.isMain = function() {
	return true;
};

/* 콜백명 */
scwin.callbackFncName = ''

/**
 * 공지 팝업창 패이지 onload
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function () {

	setTimeout(function(){
        pgjUtil.setPopUpCloseNextTabEvent($p.getFrame());
    }, 500);

	/* 메인페이로부터 공지사항 제목,내용 데이터를 전달 받아 화면으로 전송. */
	param = com.data.getParameter();
	/* 콜백함수 */
	scwin.callbackFncName = param.callbackFn;
	/* 메인으로부터 넘겨받은 조회된 공지사항 parameter */
	data = param.paramObj;
 	/* 상세 페이지를 눌렀을 경우 cortAuctnNtcMtrSeq 해당 법원경매공지사항순번 데이터를 삽입 */

	dma_ntcMtrSeq.set("cortAuctnNtcMtrSeq", data.ntcMtrSeq);
	/* 조회된 공지사항 제목 및 내용 */
	cbx_toDayPopUpClose.setUserData("ntcMtrSeq", data.ntcMtrSeq);
	com.executeSubmission(sbm_selectPopUpNtcMtrDtl)
};


scwin.onpageunload = function () {

};

/**
 * 팝업용 공지사항 상세조회
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.10.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_selectPopUpNtcMtrDtl_submitdone = function({responseJSON:{status,data}}) {

	if (status === 200) {
		const result = data.dlt_rcntRegNtcMtr[0];

		//개행처리
		let ntatcCtxtCtt = result.ntatcCtxtCtt;
		if(!scutilo.isEmpty(ntatcCtxtCtt)){
			ntatcCtxtCtt = ntatcCtxtCtt.replaceAll(' ', '&nbsp;').replaceAll('\n', '<br />');
		}

		tbx_ntatcTitlNm.setValue(result.ntatcTitlNm);
		tbx_ntatcCtxtCtt1.setValue(ntatcCtxtCtt);
	}
};



scwin.btn_NtcMtrPouUpClose_onclick = function(e) {
	let flagYn = cbx_toDayPopUpClose.getValue();
	let ntcMtrSeq = cbx_toDayPopUpClose.getUserData("ntcMtrSeq");
	if (flagYn == "Y") {
		pgjUtil.setCookie(ntcMtrSeq,"Y",6*60*24);
	}
};

/**
 * 상세버튼 눌렀을 경우 법원경매공지사항순번 parameter와 함께
 * 공지사항 팝업창 close하면서 메인페이지 callback함수 실행
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.07.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_ntcMtrDtl_onclick = function(e) {

	/*공지사항 상세정보  */
	var moveData ={
		"cortAuctnNtcMtrSeq" : dma_ntcMtrSeq.get("cortAuctnNtcMtrSeq")
	};
	com.win.closePopup(scwin.callbackFncName,moveData);
};
